'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={journey:'M3 19h18M5 17l4-7 4 1 2 6M9 10l2-5 4 3 4 1M11 3h4M6 16l-2 4M15 17l4 3',map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2V5zM9 3v16M15 5v16',stations:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8',book:'M12 5c-3-3-7-2-10-2v16c4-1 7 0 10 2 3-2 6-3 10-2V3c-4 0-7-1-10 2zM12 5v16',records:'M5 4h14v18H5zM9 2h6v4H9zM8 10h8M8 14h8M8 18h5',plus:'M12 5v14M5 12h14',close:'M6 6l12 12M18 6L6 18',settings:'M4 6h16M4 12h16M4 18h16M9 3v6M15 9v6M9 15v6',arrow:'M5 12h14M14 7l5 5-5 5',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.arrow}"/></svg>`}
const KEY='aruku-tokaido-v1',TOTAL=495600,VERSION=1;
const fresh=()=>({version:VERSION,records:[],settings:{preview:false,font:18},read:[]});
let state=fresh(),storeOK=true,corruptRaw=null,page='journey',diaryTab='stories',unreadOnly=false,stationFilter='all',searchTerm='',selectedMap=0,importCandidate=null;
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const total=()=>state.records.reduce((a,r)=>a+r.meters,0);
const travel=()=>Math.min(TOTAL,total());
const km=m=>(m/1000).toLocaleString('ja-JP',{minimumFractionDigits:1,maximumFractionDigits:2});
function currentIndex(m=travel()){let n=0;while(n<54&&STATIONS[n+1].km*1000<=m+.001)n++;return n}
function validDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===s&&s>='1900-01-01'&&s<=today()}
function validate(v){
 if(!v||v.version!==1||!Array.isArray(v.records)||v.records.length>10000)throw Error('このアプリの形式（version 1）ではありません。');
 const ids=new Set();const records=v.records.map(r=>{
  if(!r||typeof r.id!=='string'||r.id.length>100||!r.id||ids.has(r.id)||!validDate(r.date)||!Number.isInteger(r.meters)||r.meters<1||r.meters>1000000||typeof r.note!=='string'||r.note.length>300)throw Error('記録の形式・日付・距離に不正な値があります。');
  ids.add(r.id);return {id:r.id,date:r.date,meters:r.meters,note:r.note};
 });
 const settings={preview:v.settings?.preview===true,font:[17,18,20,22].includes(v.settings?.font)?v.settings.font:18};
 const read=Array.isArray(v.read)?[...new Set(v.read.filter(x=>STORIES.some(s=>s.id===x)))]:[];
 return {version:1,records,settings,read};
}
function storageAlert(msg){$('#storage-alert').textContent=msg;$('#storage-alert').classList.remove('hidden')}
try{const raw=localStorage.getItem(KEY);if(raw){try{state=validate(JSON.parse(raw))}catch(e){corruptRaw=raw;storageAlert('保存済みデータを読み込めませんでした。元データは保持しています。「設定」から退避できます。')}}localStorage.setItem(KEY+'-test','1');localStorage.removeItem(KEY+'-test')}catch(e){storeOK=false;storageAlert('この環境では端末内に保存できません。記録後は必ず書き出しをしてください。通常のChromeで開き直すことをおすすめします。')}
function save(next){
 try{next=validate(next)}catch(e){toast(e.message);return false}
 try{if(corruptRaw){localStorage.setItem(KEY+'-recovery',corruptRaw);corruptRaw=null}localStorage.setItem(KEY,JSON.stringify(next));storeOK=true}catch(e){storeOK=false;storageAlert('保存に失敗しました。記録はこの画面に残っていますが、閉じる前に「記録を書き出す」で保管してください。')}
 state=next;return true;
}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3300)}
function openDrawer(kind,content){$('#dialog-kind').textContent=kind;$('#drawer-body').innerHTML=content;$('#drawer-body').scrollTop=0;if(!$('#drawer').open)$('#drawer').showModal();document.body.style.overflow='hidden';handleImages()}
function closeDrawer(){$('#drawer').close();document.body.style.overflow=''}
$('#drawer').addEventListener('close',()=>document.body.style.overflow='');
$('#close-drawer').innerHTML=icon('close');$('#close-drawer').onclick=closeDrawer;
$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer')){const r=e.target.getBoundingClientRect();if(e.clientY<r.top)closeDrawer()}});
$('#settings').innerHTML=icon('settings');$('#settings').onclick=showSettings;
function artImage(i,cls='',loading='lazy'){return `<img class="${cls}" src="${ART[i]}" alt="歌川広重『${esc(STATIONS[i].name)}・${esc(STATIONS[i].title)}』保永堂版の構図" loading="${loading}">`}
function handleImages(){ $$('img').forEach(img=>img.onerror=()=>{const el=document.createElement('div');el.className='bad-image';el.textContent='画像を表示できません。下の出典からご覧ください。';img.replaceWith(el)}) }
function artCredit(i){const s=STATIONS[i];return `歌川広重『東海道五拾三次』保永堂版の構図<br>${s.reproduction?'掲載画像は高見澤による後世の小型復刻版。原摺ではありません。<br>':''}<a href="${s.artSource}" target="_blank" rel="noopener noreferrer">画像の出典・権利表示（Wikimedia Commons） ↗</a>／パブリックドメイン（著作権保護期間満了）`}
function walker(){return `<img src="data:image/png;base64," alt="左を向いて西へ歩く弥次郎兵衛と喜多八・アプリ用イラスト" style="width:100%;height:100%;object-fit:contain">`}
function nav(){const names=[['journey','旅'],['map','地図'],['stations','宿場'],['diary','道中記'],['records','記録']];$('#nav').innerHTML=names.map(([id,n])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id==='diary'?'book':id)}<span>${n}</span></button>`).join('');$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page))}
function go(p){page=p;render();window.scrollTo(0,0)}
function head(en,title,side=''){return `<div class="page-head"><div><div class="eyebrow">${en}</div><h1>${title}</h1></div>${side}</div>`}
function render(){nav();({journey:renderJourney,map:renderMap,stations:renderStations,diary:renderDiary,records:renderRecords})[page]();handleImages()}
function readingCount(){return STORIES.filter(s=>state.read.includes(s.id)).length}
function nextUnread(){return STORIES.find(s=>!state.read.includes(s.id)&&(state.settings.preview||STATIONS[s.station].km*1000<=travel()))||STORIES.find(s=>!state.read.includes(s.id))}
function readingProgress(){const count=readingCount(),finished=count===STORIES.length,walked=travel()===TOTAL,next=nextUnread();return `<section class="reading-progress ${finished?'finished':''}" aria-label="読了の進捗"><div class="eyebrow">${finished&&walked?'旅も、物語も、読み終えました':finished?'収録した読み物を完読':'歩く旅と、読む旅'}</div><div class="reading-score"><strong>${count}<small> / ${STORIES.length} 篇</small></strong><span>${finished?'完読 ✓':'読了'}</span></div><progress max="${STORIES.length}" value="${count}" aria-label="${STORIES.length}篇中${count}篇を読了"></progress><p class="small">日本橋＋53宿＋三条大橋、全55地点に読み物があります。四日市の先からは、伊勢・京都・大坂の原作を別旅程として読み進めます。</p>${next?`<button class="btn primary full" data-resume="${next.id}">${count?'未読のつづきを読む':'第1篇から読む'} ${icon('arrow')}</button>`:`<p class="completion-message">${walked?'東海道踏破 ＋ 収録56篇完読、おめでとうございます。':'収録56篇、すべて読了。京都までの歩く旅も楽しんでください。'}</p>`}<p class="source">完読はこのアプリに収録した場面の読了です。原作全集の全文訳・『続膝栗毛』の全話収録ではありません。</p></section>`}
function wireReadingProgress(){$$('[data-resume]').forEach(b=>b.onclick=()=>showStory(b.dataset.resume))}
function storyCard(s){const available=STATIONS[s.station].km*1000<=travel(),order=STORIES.indexOf(s)+1,detour=s.kind==='detour';return `<button class="story-preview ${detour?'detour-story':''}" data-story="${s.id}"><div><span class="tag">第${order}篇 ・ ${detour?'原作の別旅程':'東海道の道中'}</span><h3>${esc(s.title)}</h3><p class="story-place">${esc(s.place)}</p><p>${esc(s.text[0].slice(0,44))}…</p><span class="readmark">${state.read.includes(s.id)?'読了 ✓':'未読 ・ 約'+Math.ceil(s.text.join('').length/350)+'分'}　→</span><small class="unlock-label">${available?'到達済':STATIONS[s.station].name+'で解放 ・ 先読み可'}</small></div>${artImage(s.station)}</button>`}
function wireStories(){ $$('[data-story]').forEach(b=>b.onclick=()=>showStory(b.dataset.story)) }
function renderJourney(){const n=currentIndex(),s=STATIONS[n],next=STATIONS[Math.min(54,n+1)],done=STATIONS.slice(1,54).filter(x=>x.km*1000<=travel()).length;const accessible=STORIES.filter(x=>STATIONS[x.station].km*1000<=travel());
 $('#main').innerHTML=`${head('THE TOKAIDO JOURNEY','今日も、道のつづきへ。',`<span class="pill">${done} / 53 宿</span>`)}<div class="hero">${artImage(n,'','eager')}<div class="hero-label"><div class="eyebrow">${n===0?'旅のはじまり':n===54?'東海道踏破':'第 '+n+' 宿 からの道'}</div><h2>${s.name}${n>0&&n<54?'宿':''}</h2><p>${n===54?'江戸から京へ。歩いてつないだ495.6km。':next.name+'まで、あと '+km(next.km*1000-travel())+' km'}</p></div><div class="hero-no">${String(n).padStart(2,'0')}</div></div><div class="art-caption">広重「${s.name}・${s.title}」${s.reproduction?'／後世の復刻版':''}</div><div class="summary-top"><div><div class="eyebrow">累計歩行距離</div><div class="distance" id="total-km">${km(total())}<span>km</span></div></div><div><div class="eyebrow">踏破率</div><div class="progress-percent">${(travel()/TOTAL*100).toFixed(1)}<small> %</small></div></div></div><div class="track" aria-label="右の日本橋から左の京都へ。踏破率${(travel()/TOTAL*100).toFixed(1)}パーセント"><div class="track-line"><div class="track-done" style="width:${travel()/TOTAL*100}%"></div></div><span class="track-end west"></span><span class="track-end east"></span><div class="walker" id="walker" style="left:${100-travel()/TOTAL*100}%">${walker()}</div><div class="track-labels"><span class="west-label">← 西・京都 三条大橋</span><span>東・江戸 日本橋</span></div></div><div class="metrics"><div class="metric"><small>${n===54?'全行程':`次の${next.name}まで`}</small><b>${n===54?km(TOTAL):km(next.km*1000-travel())}</b><span>km</span></div><div class="metric"><small>京都 三条大橋まで</small><b>${km(TOTAL-travel())}</b><span>km</span></div></div><button class="btn primary full" id="add-walk">${icon('plus')} 今日の歩きを記す</button>${n>=41&&n<42?'<div class="note">今は七里の渡しの区間。江戸時代の旅人は、ここを船で渡りました。</div>':''}${n>=43&&n<54?'<div class="note">原作の弥次喜多は、四日市の先の追分から伊勢へ。このアプリの東海道ルートとは旅程が分かれます。</div>':''}${readingProgress()}<div class="section-head"><h2>道中のひとこま</h2><span class="small muted">${accessible.length} / ${STORIES.length} 話</span></div>${storyCard(accessible[accessible.length-1])}<button class="btn text" id="all-stories">道中記をひらく ${icon('arrow')}</button><div class="section-head"><h2>今いる場所を、地図で。</h2></div><button class="btn full" id="open-map">${icon('map')} ${s.name}付近を見る</button><p class="small muted" style="margin-top:18px">歩いた距離を江戸から京の旅に重ねる、約495.6kmの道中です。地図の位置は距離から換算した仮想の現在地です。</p>`;
 $('#add-walk').onclick=()=>recordForm();$('#all-stories').onclick=()=>go('diary');$('#open-map').onclick=()=>{selectedMap=n;mapMode='detail';mapFollow=true;go('map')};wireStories();wireReadingProgress();
}
function stationRow(s){const reached=s.km*1000<=travel(),endpoint=s.id===0||s.id===54;return `<button class="station-row ${endpoint?'endpoint':''}" data-station="${s.id}"><div class="num ${endpoint?'endnum':''}">${endpoint?(s.id===0?'発':'着'):String(s.id).padStart(2,'0')}</div>${artImage(s.id)}<div class="row-text"><strong>${s.name}</strong><small>${esc(s.location)}</small></div><div class="row-right">${s.km.toFixed(1)}<small>km</small><span class="pill ${reached?'done':''}">${reached?'到達済':'未到達'}</span></div></button>`}
function wireStations(){ $$('[data-station]').forEach(b=>b.onclick=()=>showStation(Number(b.dataset.station))) }
function renderStations(){ $('#main').innerHTML=`${head('FIFTY-THREE STATIONS','五十三の宿場')}<p class="small muted">日本橋から三条大橋へ。宿場の名を押して、歴史と広重の風景をひらきます。</p><input class="search" id="station-search" type="search" placeholder="宿場・地名で探す" aria-label="宿場・地名で探す" value="${esc(searchTerm)}"><div class="segmented"><button id="filter-all" class="${stationFilter==='all'?'active':''}">すべて</button><button id="filter-reached" class="${stationFilter==='reached'?'active':''}">到達済</button></div><div id="station-count" class="small muted"></div><div id="station-list"></div>`;
 $('#station-search').oninput=e=>{searchTerm=e.target.value;stationList()};$('#filter-all').onclick=()=>{stationFilter='all';renderStations()};$('#filter-reached').onclick=()=>{stationFilter='reached';renderStations()};stationList() }
function stationList(){const q=searchTerm.trim();const list=STATIONS.filter(s=>(stationFilter==='all'||s.km*1000<=travel())&&(!q||[s.name,s.location,s.feature,s.reading||''].some(x=>x.includes(q))));$('#station-count').textContent=`${list.filter(x=>x.id>0&&x.id<54).length}宿 ＋ 起終点${list.filter(x=>x.id===0||x.id===54).length}地点`;$('#station-list').innerHTML=list.length?list.map(stationRow).join(''):'<div class="empty">該当する宿場はありません。</div>';wireStations();handleImages()}
function showStation(id){const s=STATIONS[id],reached=s.km*1000<=travel(),ss=STORIES.filter(x=>x.station===id);openDrawer('宿場を訪ねる',`<div class="eyebrow">${id===0?'出発地':id===54?'到着地':'第 '+id+' 宿'} ・ ${reached?'到達済':'未到達'}</div><h2 id="dialog-title">${s.name}${id>0&&id<54?'宿':''}</h2><p class="small muted">${s.location}</p><div class="wide-art">${artImage(id,'','eager')}</div><div class="source">${artCredit(id)}</div><h3>「${s.name}・${s.title}」</h3><p class="small">${s.look}</p><div class="detail-km"><div><small>日本橋から</small><b>${s.km.toFixed(1)} <small>km</small></b></div><div><small>${id===54?'旅の終点':'次の'+STATIONS[id+1].name+'まで'}</small><b>${s.nextKm.toFixed(1)} <small>km</small></b></div></div><p>${s.feature}</p><dl class="facts"><div><dt>代表的な史跡・歴史を伝える場所</dt><dd>${s.landmark}</dd></div><div><dt>江戸の名物・道中の名産</dt><dd>${s.specialty}</dd></div><div><dt>街道上の特徴</dt><dd>${s.road}</dd></div></dl>${id>=44&&id<=53?'<div class="note">この宿はウォーキング上の東海道五十三次ルートです。原作の二人が伊勢へ向かった道筋と混同しないよう、この宿で開く読み物は、伊勢・京都・大坂での原作の別旅程です。この宿を二人が訪れた話ではありません。</div>':''}<div class="source">宿場史：<a href="${s.source}" target="_blank" rel="noopener noreferrer">自治体・観光機関等の資料 ↗</a><br>名物：<a href="${s.foodSource}" target="_blank" rel="noopener noreferrer">参照資料 ↗</a><br>名物欄は宿内だけでなく近隣の道中を含みます。「参考資料の記載」は江戸期の成立年代まで確認できていない項目です。</div>${ss.length?`<h3>${id>=44?'この地点で開く原作の別旅程':'この付近の道中記'}</h3>`+ss.map(storyCard).join(''):''}<button class="btn full" id="station-map">${icon('map')} 地図でこの宿を見る</button><p class="source">距離は歴史資料の換算に基づく目安。現在の道路を歩いた実測距離ではありません。次宿距離は丸めた累計値の差です。</p>`);$('#station-map').onclick=()=>{closeDrawer();selectedMap=id;mapMode='detail';mapFocus=id;go('map')};wireStories()}
function renderDiary(){ $('#main').innerHTML=`${head('YAJI & KITA / HIROSHIGE','道中記をひらく')}<div class="segmented"><button data-diary="stories" class="${diaryTab==='stories'?'active':''}">読み物 ${STORIES.length}</button><button data-diary="art" class="${diaryTab==='art'?'active':''}">広重 55図</button><button data-diary="sources" class="${diaryTab==='sources'?'active':''}">資料と出典</button></div><div id="diary-content"></div>`;$$('[data-diary]').forEach(b=>b.onclick=()=>{diaryTab=b.dataset.diary;renderDiary()});
 if(diaryTab==='stories'){const list=STORIES.filter(s=>!unreadOnly||!state.read.includes(s.id));$('#diary-content').innerHTML=`${readingProgress()}<p class="small muted">各地点で原作の一場面を読み進めます。短い原文、独自の現代語化、参照頁の原文を収録。本文を開くだけでは読了になりません。読み終えたら末尾の「読了」を押してください。</p><label class="toggle"><input id="preview-toggle" type="checkbox" ${state.settings.preview?'checked':''}>未到達の物語も先読みする</label><div class="segmented"><button id="reading-all" class="${unreadOnly?'':'active'}">すべて</button><button id="reading-unread" class="${unreadOnly?'active':''}">未読 ${STORIES.length-readingCount()}</button></div>${list.length?list.map((s,i)=>`${i===0||s.kind!==list[i-1].kind?`<div class="section-head"><h2>${s.kind==='detour'?'伊勢・京都・大坂の原作へ':'日本橋から四日市の道中'}</h2></div>${s.kind==='detour'?'<div class="note">ここから原作の舞台は伊勢・大和・京都・大坂へ。歩行地図は東海道を京都へ進み、読書だけが別の旅程をたどります。</div>':''}`:''}${storyCard(s)}`).join(''):'<div class="empty">収録した読み物はすべて読了です。<br>「すべて」から読み返せます。</div>'}`;$('#preview-toggle').onchange=e=>{save({...state,settings:{...state.settings,preview:e.target.checked}});renderDiary();toast(e.target.checked?'すべての読み物を読めます':'到達に合わせて読み物を開きます')};$('#reading-all').onclick=()=>{unreadOnly=false;renderDiary()};$('#reading-unread').onclick=()=>{unreadOnly=true;renderDiary()};wireStories();wireReadingProgress()}
 else if(diaryTab==='art'){$('#diary-content').innerHTML=`<p class="small muted">日本橋・53宿・三条大橋の55図。すべて保永堂版の構図です。一部に後世の復刻版を含み、各画像に明記しています。</p><div class="gallery">${STATIONS.map(s=>`<button data-station="${s.id}">${artImage(s.id)}<h3>${s.id===0?'発':s.id===54?'着':s.id}　${s.name}</h3><small>${s.title}${s.reproduction?' ・ 復刻版':''}</small></button>`).join('')}</div>`;wireStations()}
 else $('#diary-content').innerHTML=sourcesHTML();handleImages();
}
function showStory(id,force=false){const s=STORIES.find(x=>x.id===id);if(!s)return;const available=STATIONS[s.station].km*1000<=travel();if(!available&&!state.settings.preview&&!force){openDrawer('先の道中を読む',`<div class="eyebrow">${s.place}</div><h2 id="dialog-title">${s.title}</h2><p>この物語は${STATIONS[s.station].name}到着時に開きます。今すぐ読みたい場合は、先読みを有効にできます。</p><p class="small muted">到達まで、あと ${km(STATIONS[s.station].km*1000-travel())} km</p><button class="btn primary full" id="enable-preview">先読みをオンにして読む</button>`);$('#enable-preview').onclick=()=>{save({...state,settings:{...state.settings,preview:true}});showStory(id)};return}
 const order=STORIES.indexOf(s)+1,detour=s.kind==='detour';let imgs='';if(s.illustration){const p=s.illustration;imgs+=`<h3>${id==='departure'?'原作版本の口絵（参考図）':'この場面の原作挿絵'}</h3><button class="image-open" data-book="${p}" style="padding:0;width:100%"><img class="book-image" src="${BOOK[p]}" alt="十返舎一九・${esc(s.part)}の版本${p}コマ目"></button><p class="book-caption">${id==='departure'?'初編の道中を描く口絵。上の出発本文そのものの挿絵とは断定しません。':'初編の湯殿の場面。下駄で入る風呂と二人の様子が描かれています。'}<br>国文学研究資料館蔵・紙屋利助版。画像は原作版本のもので、初版本とは断定しません。全体の${p}コマ目。タップで拡大。</p>`}
 const pages=s.pages.filter(p=>p!==s.illustration&&BOOK[p]);
 openDrawer('東海道中膝栗毛を読む',`<div class="eyebrow">第${order}篇 / ${STORIES.length} ・ ${esc(s.place)}</div><h2 id="dialog-title">${s.title}</h2>${detour?`<div class="note route-difference"><strong>原作の舞台：${esc(s.place.replace('原作：',''))}</strong><br>歩行上は${STATIONS[s.station].name}への到達で解放。ここで原作の二人がこの宿を訪れる、という意味ではありません。</div>`:''}<p class="small muted">十返舎一九『東海道中膝栗毛』${s.part}<br>一節の現代語化 ・ 約${Math.ceil(s.text.join('').length/350)}分</p><div class="eyebrow">原文（短い抜粋）</div><blockquote class="quote">${esc(s.quote)}</blockquote><div class="reading-tools"><strong class="small">現代語で読む</strong><div><button id="font-smaller" aria-label="文字を小さく">あ−</button> <button id="font-larger" aria-label="文字を大きく">あ＋</button></div></div><article class="reading" id="reading" style="font-size:${state.settings.font}px">${s.text.map(p=>`<p>${esc(p)}</p>`).join('')}</article>${originalReader(s)}<h3>この場面について</h3><div class="note">${s.note}</div>${imgs}${pages.length?`<details><summary>該当本文の版本画像を見る（挿絵ではありません）</summary>${pages.map(p=>`<button class="image-open" data-book="${p}" style="padding:0;width:100%"><img class="book-image" src="${BOOK[p]}" loading="lazy" alt="原作版本・第${p}コマ"></button><p class="book-caption">第${p}コマ／本文の影印</p>`).join('')}</details>`:''}${!s.illustration?'<p class="book-caption">この場面に対応する原作挿絵は、今回の収録資料では特定できていません。以下は広重の参考図です。</p>':''}<h3>参考図：歌川広重</h3>${detour?'<p class="book-caption">歩行上の東海道の宿場図です。この別旅程の原作場面を描く絵ではありません。</p>':''}${artImage(s.station)}<p class="small">${STATIONS[s.station].name}・${STATIONS[s.station].title}</p><div class="source">${artCredit(s.station)}</div><details><summary>本文・画像の出典と編集方針</summary><div class="source">原文確認：<a href="${s.source}" target="_blank" rel="noopener noreferrer">${esc(s.part)} 公開翻刻（左大臣光永） ↗</a><br>版本：<a href="https://codh.rois.ac.jp/pmjt/book/200004002/" target="_blank" rel="noopener noreferrer">『日本古典籍データセット』国文学研究資料館蔵／資料ID 200004002 ↗</a><br>画像提供：ROIS-DS人文学オープンデータ共同利用センター。CC BY-SA 4.0（表示・継承）。画像は縮小のみで改変せず掲載。<br>現代語部分は公開翻刻の原文に基づく本アプリ独自の現代語化です。掲載サイトの既存現代語訳は転載していません。句読点・表記は読みやすく整理し、省略範囲は「この場面について」に記しています。専門家の校訂を経た翻訳ではありません。</div></details><div class="reader-end"><p class="small muted" id="reader-score">${readingCount()} / ${STORIES.length}篇 読了</p><button class="btn primary full" id="mark-read">${state.read.includes(id)?'読了済み ✓':'この話を読了にする'}</button><button class="btn full" id="read-next">読了して${order<STORIES.length?'次の話へ':'道中記へ'}</button><div class="reader-pager">${order>1?'<button id="previous-story">前の話</button>':'<span></span>'}${order<STORIES.length?'<button id="next-story">次の話</button>':'<span></span>'}</div>${state.read.includes(id)?'<button class="btn text full" id="undo-read">この話を未読に戻す</button>':''}</div>`);
 function changeFont(delta){const sizes=[17,18,20,22],i=Math.max(0,Math.min(3,sizes.indexOf(state.settings.font)+delta));save({...state,settings:{...state.settings,font:sizes[i]}});$('#reading').style.fontSize=sizes[i]+'px'}$('#font-smaller').onclick=()=>changeFont(-1);$('#font-larger').onclick=()=>changeFont(1);
 function mark(){if(!save({...state,read:[...new Set([...state.read,id])]}))return false;render();return true}$('#mark-read').onclick=()=>{if(mark()){showStory(id);toast(readingCount()===STORIES.length?'収録56篇を完読しました':'読了を記しました')}};$('#read-next').onclick=()=>{if(!mark())return;if(order<STORIES.length)showStory(STORIES[order].id);else{closeDrawer();diaryTab='stories';go('diary');toast(readingCount()===STORIES.length?'収録56篇を完読しました':'まだ未読の話があります')}};if($('#previous-story'))$('#previous-story').onclick=()=>showStory(STORIES[order-2].id);if($('#next-story'))$('#next-story').onclick=()=>showStory(STORIES[order].id);if($('#undo-read'))$('#undo-read').onclick=()=>{save({...state,read:state.read.filter(x=>x!==id)});render();showStory(id);toast('未読に戻しました')};$$('[data-book]').forEach(b=>b.onclick=()=>showBook(Number(b.dataset.book),id));
}
function originalReader(s){return `<details class="original-reader"><summary>参照頁の原文を読む（確認した翻刻本文）</summary><p class="small muted">以下は現代語化の根拠とした公開翻刻の本文部分です。参照頁の前後の場面も含みます。ルビ・異体字・表記は翻刻に従い、改行を整理しています。校異の確定や原版本との全字照合を行った校訂本文ではありません。版や翻刻により読みが異なる場合があります。</p>${(s.rawFiles||[]).map(f=>{const r=RAW_TEXT[f];return r?`<h3>${esc(r.title)}</h3><div class="original-text">${esc(r.text)}</div><p class="source"><a href="${r.url}" target="_blank" rel="noopener noreferrer">公開翻刻の参照頁（左大臣光永） ↗</a></p>`:''}).join('')}</details>`}
function showBook(n,back){openDrawer('原作版本の画像',`<h2 id="dialog-title" style="font-size:20px">版本 第${n}コマ</h2><p class="small muted">画像を押すと原寸に拡大します。拡大後は左右にもスクロールできます。</p><div class="image-modal"><img id="large-book" src="${BOOK[n]}" alt="原作版本第${n}コマ"></div><p class="source">国文学研究資料館蔵／CODH日本古典籍データセット、CC BY-SA 4.0（表示・継承）</p><button class="btn full" id="back-story">物語へ戻る</button>`);$('#large-book').onclick=e=>e.target.classList.toggle('zoomed');$('#back-story').onclick=()=>showStory(back)}
function renderRecords(){
 const sorted=[...state.records].sort((a,b)=>a.date.localeCompare(b.date)||state.records.indexOf(a)-state.records.indexOf(b));let c=0;const cumulative={};sorted.forEach(r=>{c+=r.meters;cumulative[r.id]=c});
 $('#main').innerHTML=head('WALKING LOG','歩いた日々')+`<div class="summary-top"><div><div class="eyebrow">これまでの歩行距離</div><div class="distance">${km(total())}<span>km</span></div></div><span class="pill">${state.records.length}件</span></div><p class="small muted">旅の換算は495.6kmで到着。到着後も歩行記録を続けられます。</p><button class="btn primary full" id="new-record">${icon('plus')} 歩いた距離を記す</button><div class="section-head"><h2>道中の足あと</h2><span class="small muted">新しい日付から</span></div>${sorted.length?sorted.reverse().map(r=>`<div class="record-row"><div class="record-info"><div><strong>${r.date.replaceAll('-',' / ')}</strong><div class="small muted">この記録までの累計 ${km(cumulative[r.id])} km</div></div><b>${km(r.meters)} <small>km</small></b></div>${r.note?`<p class="record-note">${esc(r.note)}</p>`:''}<div class="record-actions"><button data-edit="${esc(r.id)}">修正</button><button class="danger" data-delete="${esc(r.id)}">削除</button></div></div>`).join(''):'<div class="empty">まだ、旅の記録がありません。<br>今日歩いた距離から始めましょう。</div>'}<div class="section-head"><h2>記録を持ち運ぶ</h2></div><div class="row-actions"><button class="btn" id="export">${icon('download')} 書き出す</button><button class="btn" id="import">読み込む</button></div><p class="small muted" style="margin-top:12px">JSON形式。端末の変更やファイルの移動前には書き出して保管してください。</p>`;
 $('#new-record').onclick=()=>recordForm();$$('[data-edit]').forEach(b=>b.onclick=()=>recordForm(b.dataset.edit));$$('[data-delete]').forEach(b=>b.onclick=()=>deleteRecord(b.dataset.delete));$('#export').onclick=exportData;$('#import').onclick=()=>$('#import-file').click();
}
function recordForm(id){const r=state.records.find(x=>x.id===id);openDrawer(r?'歩行記録を修正':'きょうの一歩を記す',`<h2 id="dialog-title">${r?'記録を修正する':'今日は、何km歩きましたか。'}</h2><form id="record-form"><label class="field"><span>歩いた日</span><input type="date" id="record-date" required min="1900-01-01" max="${today()}" value="${r?.date||today()}"></label><label class="field"><span>歩いた距離（km）</span><input class="km-input" type="number" inputmode="decimal" id="record-distance" step="0.001" min="0.001" max="1000" required placeholder="0.0" value="${r?r.meters/1000:''}"></label><div class="quick">${[1,3,5,10].map(n=>`<button type="button" data-distance="${n}">${n} km</button>`).join('')}</div><label class="field"><span>ひとこと（任意・300字まで）</span><input type="text" id="record-note" maxlength="300" value="${esc(r?.note||'')}" placeholder="夕方、川沿いを歩いた"></label><p class="small muted">距離は手入力です。歩数・GPSの自動取得はしません。同じ日に複数回記録できます。</p><p id="form-error" class="danger small" role="alert"></p><button class="btn primary full" type="submit">${r?'修正して保存':'旅を進める'}</button></form>`);
 $$('[data-distance]').forEach(b=>b.onclick=()=>$('#record-distance').value=b.dataset.distance);$('#record-form').onsubmit=e=>{e.preventDefault();const meters=Math.round(Number($('#record-distance').value)*1000),date=$('#record-date').value,note=$('#record-note').value;if(!validDate(date)||!Number.isFinite(meters)||meters<1||meters>1000000){$('#form-error').textContent='日付と距離を確認してください。距離は0.001〜1000kmです。';return}const before=travel(),newRecord={id:r?.id||globalThis.crypto?.randomUUID?.()||('walk-'+Date.now()+'-'+Math.random().toString(36).slice(2)),date,meters,note};const records=r?state.records.map(x=>x.id===id?newRecord:x):[...state.records,newRecord];if(!save({...state,records}))return;closeDrawer();render();const reached=STATIONS.filter(s=>s.id>0&&s.km*1000>before&&s.km*1000<=travel());if(reached.length)showArrival(reached);else toast(storeOK?'記録を保存しました':'記録を追加しました。書き出して保管してください。')};
}
function deleteRecord(id){const r=state.records.find(x=>x.id===id);if(!r)return;openDrawer('記録の削除',`<h2 id="dialog-title">この記録を削除しますか。</h2><p>${r.date} ・ ${km(r.meters)} km</p><p class="small muted">累計と現在位置を計算し直します。読了印は残ります。</p><div class="row-actions"><button class="btn" id="cancel-delete">戻る</button><button class="btn red" id="confirm-delete">削除する</button></div>`);$('#cancel-delete').onclick=closeDrawer;$('#confirm-delete').onclick=()=>{save({...state,records:state.records.filter(x=>x.id!==id)});closeDrawer();render();toast('記録を削除しました')}}
function showArrival(list,index=list.length-1){const s=list[index];openDrawer('宿場に到着しました',`<div class="arrival"><div class="arrival-stamp">${s.id===54?'踏破':'到着'}</div><div class="eyebrow">${s.id===54?'THE END OF TOKAIDO':'A NEW POST TOWN'}</div><h2 id="dialog-title">${s.id===54?'京都・三条大橋 到着':`第${s.id}宿 ${s.name}宿 到着`}</h2>${artImage(s.id)}<p>${s.feature}</p></div><div class="source">${artCredit(s.id)}</div>${s.id===54?readingProgress():''}${list.length>1?`<p class="small">今回、${list.length}地点に到達しました。下の宿場も開けます。</p><div class="arrival-list">${list.map((x,i)=>`<button data-arrival="${i}">${x.name}</button>`).join('')}</div>`:''}<button class="btn primary full" id="arrival-detail">${s.name}を訪ねる</button>${STORIES.filter(x=>x.station===s.id).map(x=>`<button class="btn full" data-arrival-story="${x.id}" style="margin-top:10px">道中記：${x.title}</button>`).join('')}`);$$('[data-arrival]').forEach(b=>b.onclick=()=>showArrival(list,Number(b.dataset.arrival)));$('#arrival-detail').onclick=()=>showStation(s.id);$$('[data-arrival-story]').forEach(b=>b.onclick=()=>showStory(b.dataset.arrivalStory));wireReadingProgress();}
function downloadText(text,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function exportData(){downloadText(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'tokaido-records-'+today()+'.json');toast('記録ファイルを書き出しました')}
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('10MB以下の記録ファイルを選んでください。');importCandidate=validate(JSON.parse(await file.text()));const sum=importCandidate.records.reduce((a,r)=>a+r.meters,0);openDrawer('記録の読み込み',`<h2 id="dialog-title">読み込む内容を確認</h2><p>${importCandidate.records.length}件の記録<br>合計 ${km(sum)} km</p><p class="small muted">「追加」は同じIDの記録を重複させず、端末側の内容を優先します。「置き換え」は現在の記録・設定・読了印をこのファイルの内容に変更します。</p><button class="btn primary full" id="merge-import">現在の記録に追加</button><button class="btn full" id="replace-import" style="margin-top:12px">確認して置き換える</button>`);$('#merge-import').onclick=()=>applyImport(false);$('#replace-import').onclick=()=>{openDrawer('置き換えの最終確認',`<h2 id="dialog-title">現在の${state.records.length}件を置き換えますか。</h2><p>必要なら、現在の記録を先に書き出してください。</p><div class="row-actions"><button class="btn" id="before-export">現在の記録を書き出す</button><button class="btn red" id="confirm-replace">置き換える</button></div>`);$('#before-export').onclick=exportData;$('#confirm-replace').onclick=()=>applyImport(true)}}catch(err){importCandidate=null;toast('読み込めません：'+err.message)}};
function applyImport(replace){if(!importCandidate)return;const ids=new Set(state.records.map(r=>r.id)),next=replace?importCandidate:{...state,records:[...state.records,...importCandidate.records.filter(r=>!ids.has(r.id))],read:[...new Set([...state.read,...importCandidate.read])]};if(!save(next))return;importCandidate=null;closeDrawer();render();toast('記録を読み込みました')}
function sourcesHTML(){return `<h2>資料をたどる</h2><p class="small">原作本文、浮世絵、地理と距離は別の資料です。個々の宿場・物語にも対応する出典を載せています。</p><ul class="sources-list"><li><a href="https://roudokus.com/Hizakurige/" target="_blank" rel="noopener">『東海道中膝栗毛』公開翻刻（左大臣光永）</a>：原文の確認。現代語部分は本アプリ独自の現代語化。</li><li><a href="https://codh.rois.ac.jp/pmjt/book/200004002/" target="_blank" rel="noopener">国文学研究資料館蔵『東海道中膝栗毛』紙屋利助版</a>：CODH日本古典籍データセット。資料ID 200004002。版本画像はCC BY-SA 4.0。</li><li><a href="https://geoshape.ex.nii.ac.jp/edo/post/R001/" target="_blank" rel="noopener">江戸宿場データセット・東海道</a>：ROIS-DS人文学オープンデータ共同利用センター作成、CC BY 4.0。55地点の代表座標。</li><li><a href="https://www.benricho.org/map_53tsugi/kyori.html" target="_blank" rel="noopener">宿村大概帳に基づく宿間距離表</a>：累計495.6km。丸めによる差を避け、次宿距離は累計の差で計算。</li><li><a href="https://www.gsi.go.jp/kankyochiri/gm_jpn.html" target="_blank" rel="noopener">国土地理院・地球地図日本</a>／<a href="https://github.com/dataofjapan/land" target="_blank" rel="noopener">Data of JapanのGeoJSON変換</a>：47都道府県の地理背景。簡略化して使用。<a href="https://www.gsi.go.jp/kikakuchousei/kikakuchousei40182.html" target="_blank" rel="noopener">利用規約</a>。</li><li><a href="https://rekishi-kanko.pref.aichi.jp/" target="_blank" rel="noopener">愛知県・歴史観光サイト</a>、<a href="https://www.kanagawa-kankou.or.jp/features/tokaido-syukuba" target="_blank" rel="noopener">神奈川県観光協会</a>、甲賀市・湖南市・草津市、JR東海の街道資料：歴史・史跡。各宿カードに該当ページ。</li><li><a href="https://kaido-walking.com/column/tokaidoSyukubaList.php" target="_blank" rel="noopener">街道歩き・宿場一覧</a>：名物の補助資料。江戸期の裏づけが十分でないものは断定を避け、未確認と明記。</li><li>歌川広重・保永堂版『東海道五拾三次』55図：Wikimedia Commonsの各画像ページで著作権表示を確認。掲載画像に後世の復刻を含み、その都度区別。全画像の出典は宿場カードに記載。</li></ul><div class="note">本アプリの歴史・画像資料の確認日：2026年10月4日。原作に存在する場面を選んで現代語化していますが、全編の翻訳ではありません。未確認事項を補う創作は加えていません。</div>`}
function showSettings(){openDrawer('旅の設定と使い方',`<h2 id="dialog-title">自分の歩幅で、東海道へ。</h2><label class="toggle"><input type="checkbox" id="preview-setting" ${state.settings.preview?'checked':''}>未到達の物語も先読みする</label><p class="small muted">宿場の基本情報と広重の絵は、到着前から自由に見られます。</p><h3>距離の数え方</h3><p class="small">江戸・日本橋から京都・三条大橋まで495.6kmとして換算します。歴史的な海路の距離も、実際に歩いた距離で進みます。宮〜桑名「七里の渡し」と舞阪〜新居「今切の渡し」は徒歩道ではありません。現地の歩行案内には使用できません。</p><h3>原作と、この旅の違い</h3><p class="small">『膝栗毛』の二人は、四日市の先の日永追分から伊勢参宮へ向かい、その後、大和・京都・大坂方面へ旅を続けます。このアプリは東海道五十三次を京都へ進みます。全55地点で開く56篇の読み物を収録し、四日市の先では別旅程の原作を読み進めます。読了は歩行とは別に保存し、距離を修正しても読了印は残ります。四日市以西の各宿に、二人がそのまま訪れたとする物語は作っていません。</p><h3>記録をなくさないために</h3><p class="small">記録はこのブラウザのlocalStorageに保存します。ブラウザのデータ削除やシークレットモードでは消える場合があります。HTMLファイルを直接開いた場合の保存方法はブラウザ依存です。同じファイル・場所・ブラウザで使い、移動や更新の前にはJSONを書き出してください。</p><button class="btn full" id="settings-export">記録を書き出す</button>${corruptRaw?'<button class="btn full" id="recover-export" style="margin-top:10px">読み込めなかった元データを退避</button>':''}<details><summary>オフライン・プライバシー・動作環境</summary><p>地図背景、55枚の広重画像、収録した版本画像は同梱しています。記録をサーバーに送信する機能、広告、位置情報取得はありません。外部の出典リンクを開く時のみ通信が必要です。</p><p>縦向きのモバイルChromeを想定しています。ローカルHTMLの開き方はAndroid端末・ファイルアプリによって異なります。開けない場合は同梱一式を静的Webサーバーで配信してください。</p></details><details><summary>主要資料・権利表示</summary>${sourcesHTML()}</details><p class="small muted">歩く東海道五十三次 ― 弥次喜多道中<br>バージョン 1.1 / 2026-10-04</p>`);$('#preview-setting').onchange=e=>{save({...state,settings:{...state.settings,preview:e.target.checked}});render()};$('#settings-export').onclick=exportData;if($('#recover-export'))$('#recover-export').onclick=()=>downloadText(corruptRaw,'tokaido-recovery.json')}

let mapMode='detail',mapFollow=false,mapFocus=null,mapView=null,mapBase=null,mapZoom=1;
const project=(lon,lat)=>[(lon-137)*100,-(Math.log(Math.tan(Math.PI/4+lat*Math.PI/360))*180/Math.PI-37.4)*100];
const stationPoints=STATIONS.map(s=>project(s.lon,s.lat));
const segments=STATIONS.slice(0,-1).map((s,i)=>i===41?[stationPoints[i],project(136.86,34.98),project(136.75,35.00),stationPoints[i+1]]:[stationPoints[i],stationPoints[i+1]]);
const allRoute=segments.flatMap((s,i)=>i?s.slice(1):s);
const pathOf=p=>p.map((q,i)=>(i?'L':'M')+q[0].toFixed(2)+','+q[1].toFixed(2)).join('');
const landPaths=GEOGRAPHY.map(g=>g.rings.map(r=>pathOf(r.map(p=>project(...p)))+'Z').join(''));
function segmentPosition(i,t){const p=segments[i],lengths=p.slice(1).map((q,j)=>Math.hypot(q[0]-p[j][0],q[1]-p[j][1])),sum=lengths.reduce((a,b)=>a+b,0);let d=t*sum;for(let j=0;j<lengths.length;j++){if(d<=lengths[j]||j===lengths.length-1){const u=Math.min(1,Math.max(0,d/lengths[j]));return {point:p[j].map((x,k)=>x+(p[j+1][k]-x)*u),before:p.slice(0,j+1)}}d-=lengths[j]}return {point:p.at(-1),before:p}}
function routeProgress(){const i=currentIndex(),m=travel();if(i===54)return {point:stationPoints[54],done:allRoute};const t=(m-STATIONS[i].km*1000)/(STATIONS[i+1].km*1000-STATIONS[i].km*1000),pos=segmentPosition(i,t);return {point:pos.point,done:[...segments.slice(0,i).flatMap((s,n)=>n?s.slice(1):s),...pos.before,pos.point]}}
function resetMap(){const svg=$('#route-map');if(!svg)return;const w=svg.clientWidth,h=svg.clientHeight,aspect=h/w;const corners=mapMode==='japan'?[project(128,30),project(147,46)]:[project(135.4,34.5),project(140.15,35.9)];const minX=Math.min(...corners.map(p=>p[0])),maxX=Math.max(...corners.map(p=>p[0])),minY=Math.min(...corners.map(p=>p[1])),maxY=Math.max(...corners.map(p=>p[1]));const width=Math.max(maxX-minX,(maxY-minY)/aspect)*1.14;mapBase={cx:(minX+maxX)/2,cy:(minY+maxY)/2,w:width,h:width*aspect};mapView={...mapBase};mapZoom=1;drawMap()}
function zoomMap(factor,screenPoint){if(!mapView)return;const next=Math.min(16,Math.max(1,mapZoom*factor)),f=next/mapZoom,svg=$('#route-map');let point=screenPoint||[svg.clientWidth/2,svg.clientHeight/2],ax=mapView.cx+(point[0]/svg.clientWidth-.5)*mapView.w,ay=mapView.cy+(point[1]/svg.clientHeight-.5)*mapView.h;mapView={cx:ax+(mapView.cx-ax)/f,cy:ay+(mapView.cy-ay)/f,w:mapView.w/f,h:mapView.h/f};mapZoom=next;drawMap()}
function focusMap(point){if(mapMode==='japan'){mapMode='detail';renderMap()}resetMap();zoomMap(3.5);mapView.cx=point[0];mapView.cy=point[1];drawMap()}
function renderMap(){
 $('#main').innerHTML=head('THE ROAD ACROSS JAPAN','東海道を歩く')+`<div class="segmented"><button id="japan-map" class="${mapMode==='japan'?'active':''}">日本全体図</button><button id="detail-map" class="${mapMode==='detail'?'active':''}">東海道拡大図</button></div><p class="map-help">指で上下左右に移動・2本指で拡大。番号や宿場をタップ。</p><div class="map-shell"><svg id="route-map" role="img" aria-label="日本の地理背景と東海道五十三次。拡大操作で宿場を選べます。"></svg><div class="map-north">N</div><div class="map-toolbar"><button id="zoom-in" aria-label="地図を拡大">＋</button><button id="zoom-out" aria-label="地図を縮小">−</button><button id="locate" class="locate" aria-label="現在位置へ">◎</button><button id="map-reset" class="locate" aria-label="全区間を表示">全</button></div></div><div class="map-legend"><span><i class="keyline"></i>踏破済み</span><span><i class="keyline todo"></i>これから</span><span style="color:var(--red)">● 現在位置</span></div><label for="map-station-select" class="small">55地点から選ぶ</label><select id="map-station-select" class="select">${STATIONS.map(s=>`<option value="${s.id}" ${s.id===selectedMap?'selected':''}>${s.id===0?'出発':s.id===54?'到着':String(s.id).padStart(2,'0')}　${s.name} ／ ${s.km} km</option>`).join('')}</select><div id="map-card"></div><p class="map-attribution">地図：地球地図日本（国土地理院）を加工／Data of Japan。宿場座標：『江戸宿場データセット』（ROIS-DS人文学オープンデータ共同利用センター作成）CC BY 4.0。<br>背景は端末内に収録。海岸線・県境は簡略化しています。<br><a href="https://www.gsi.go.jp/kankyochiri/gm_jpn.html" target="_blank" rel="noopener">地理資料</a> ・ <a href="https://geoshape.ex.nii.ac.jp/edo/post/R001/" target="_blank" rel="noopener">座標の出典</a></p><div class="note">ルート線は宿場の代表位置を結ぶ概略図です。現在位置も宿間距離の割合で補間した目安で、旧道を精密に復元したGPS経路ではありません。宮〜桑名は歴史的な海路を模式的に表示。地図は北が上、京都は西（左）、江戸は東（右）です。</div><div class="note warn">原作の二人は四日市の先・日永追分から伊勢へ。ここから先は、この東海道ルートと原作の旅程が分かれます。</div>`;
 $('#japan-map').onclick=()=>{mapMode='japan';renderMap()};$('#detail-map').onclick=()=>{mapMode='detail';renderMap()};$('#zoom-in').onclick=()=>zoomMap(1.5);$('#zoom-out').onclick=()=>zoomMap(1/1.5);$('#map-reset').onclick=resetMap;$('#locate').onclick=()=>focusMap(routeProgress().point);$('#map-station-select').onchange=e=>{selectedMap=Number(e.target.value);focusMap(stationPoints[selectedMap]);mapCard()};resetMap();bindMap();mapCard();if(mapFollow){mapFollow=false;focusMap(routeProgress().point)}if(mapFocus!==null){const n=mapFocus;mapFocus=null;focusMap(stationPoints[n])}
}
function mapCard(){const s=STATIONS[selectedMap];$('#map-card').innerHTML=`<div class="card map-card"><div class="eyebrow">${s.id===0?'旅のはじまり':s.id===54?'旅の終着点':`第${s.id}宿`}　${s.km*1000<=travel()?'到達済':'未到達'}</div><h3 style="margin:8px 0">${s.name} <span class="small muted">${s.location}</span></h3><p class="small" style="margin-bottom:5px">${s.feature}</p><button class="btn full" id="map-detail">宿場と浮世絵を見る</button></div>`;$('#map-detail').onclick=()=>showStation(selectedMap)}
function drawMap(){const svg=$('#route-map');if(!svg||!mapView)return;const v=mapView,k=v.w/svg.clientWidth,progress=routeProgress();svg.setAttribute('viewBox',`${v.cx-v.w/2} ${v.cy-v.h/2} ${v.w} ${v.h}`);let content=`<title>日本地図上の東海道。55地点と距離に応じた現在位置</title><g class="geography" fill="#eee9d9" stroke="#a9b8a9" stroke-width="${.65*k}" fill-rule="evenodd">${landPaths.map((d,i)=>`<path data-prefecture="${GEOGRAPHY[i].name}" d="${d}"/>`).join('')}</g>`;
 const labels=mapMode==='japan'?[['北海道',143,43.7],['東北',140.2,39.5],['関東',140,36.7],['中部',137.5,37],['近畿',135.15,35.8],['中国',132.5,35],['四国',133.7,33.2],['九州',130.7,32.3],['日本海',134.5,39],['太平洋',142,33.8]]:[['東京都',139.56,35.88],['神奈川県',139.32,35.47],['静岡県',138.24,35.26],['愛知県',137.29,35.17],['三重県',136.31,34.63],['滋賀県',136.1,35.34],['京都府',135.47,35.26],['山梨県',138.65,35.79],['長野県',137.97,36.2],['岐阜県',136.89,35.65],['駿河湾',138.65,34.65],['遠州灘',137.6,34.38],['伊勢湾',136.78,34.62]];
 content+=`<g font-family="system-ui,sans-serif" font-size="${11*k}" text-anchor="middle" fill="#697c74" pointer-events="none">${labels.map(([n,lon,lat])=>{const p=project(lon,lat);return `<text x="${p[0]}" y="${p[1]}" stroke="#f2f0e4" stroke-width="${2*k}" paint-order="stroke">${n}</text>`}).join('')}</g>`;
 content+=`<path class="route-future" d="${pathOf(allRoute)}" fill="none" stroke="#fff9e8" stroke-width="${7*k}" stroke-linejoin="round"/><path d="${pathOf(allRoute)}" fill="none" stroke="#627a7c" stroke-width="${3*k}" stroke-dasharray="${5*k} ${3*k}"/><path class="route-done" d="${pathOf(progress.done)}" fill="none" stroke="#b94a34" stroke-width="${4*k}" stroke-linejoin="round"/>`;
 const detail=mapMode==='detail';content+=`<g class="station-markers">${STATIONS.map((s,i)=>{const p=stationPoints[i],show=detail||i===0||i===54,r=(detail?(mapZoom>2?5:3):3.5)*k;return `<g class="map-station" data-station="${i}" tabindex="${show?0:-1}" role="button" aria-label="${i} ${s.name}" transform="translate(${p})" ${show?'':'style="display:none"'}><circle r="${r+7*k}" fill="transparent"/><circle r="${r}" fill="${s.km*1000<=travel()?'#b94a34':'#fffcf5'}" stroke="#344f50" stroke-width="${k}"/>${detail&&mapZoom>1.5&&i>0&&i<54?`<text y="${-9*k}" text-anchor="middle" font-size="${10*k}" fill="#193c43" stroke="#fffcf5" stroke-width="${3*k}" paint-order="stroke">${i}</text>`:''}${i===0||i===54||detail&&mapZoom>=3?`<text x="${(i===0?-8:i===54?8:7)*k}" y="${(i===0||i===54?-11:12)*k}" text-anchor="${i===0?'end':'start'}" font-size="${(i===0||i===54?12:11)*k}" font-weight="${i===0||i===54?'700':'400'}" fill="#193c43" stroke="#fffcf5" stroke-width="${3*k}" paint-order="stroke">${i===0?'江戸・日本橋':i===54?'京都・三条大橋':s.name}</text>`:''}</g>`}).join('')}</g>`;
 const p=progress.point;content+=`<g class="current-position" transform="translate(${p})" aria-label="現在位置" pointer-events="none"><circle r="${13*k}" fill="#bf50342e"/><circle r="${7*k}" fill="#b94a34" stroke="#fff" stroke-width="${2.5*k}"/><path d="M0 ${-10*k}L${-5*k} ${-18*k}H${5*k}Z" fill="#b94a34"/><rect x="${-25*k}" y="${-35*k}" width="${50*k}" height="${18*k}" rx="${4*k}" fill="#b94a34"/><text text-anchor="middle" y="${-22*k}" fill="#fff" font-size="${10*k}">現在地</text></g>`;svg.innerHTML=content;
}
function bindMap(){const svg=$('#route-map'),pointers=new Map();let last=null,moved=false,start=null;const relative=e=>{const r=svg.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]};svg.addEventListener('pointerdown',e=>{start=e.target.closest('[data-station]')?.dataset.station??null;pointers.set(e.pointerId,relative(e));svg.setPointerCapture(e.pointerId);last=null;moved=false});svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId),now=relative(e);pointers.set(e.pointerId,now);if(pointers.size===1){const dx=now[0]-old[0],dy=now[1]-old[1];if(Math.abs(dx)+Math.abs(dy)>2)moved=true;mapView.cx-=dx*mapView.w/svg.clientWidth;mapView.cy-=dy*mapView.h/svg.clientHeight;drawMap()}else{moved=true;const pts=[...pointers.values()],dist=Math.hypot(pts[0][0]-pts[1][0],pts[0][1]-pts[1][1]),mid=[(pts[0][0]+pts[1][0])/2,(pts[0][1]+pts[1][1])/2];if(last)zoomMap(dist/last,mid);last=dist}});function finish(e){if(!moved&&pointers.size===1&&start!==null){selectedMap=Number(start);$('#map-station-select').value=selectedMap;mapCard();showStation(selectedMap)}pointers.delete(e.pointerId);last=null;start=null}svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);last=null;start=null});svg.addEventListener('wheel',e=>{e.preventDefault();zoomMap(e.deltaY<0?1.15:1/1.15,relative(e))},{passive:false});svg.addEventListener('keydown',e=>{const s=e.target.closest('[data-station]');if(s&&['Enter',' '].includes(e.key)){e.preventDefault();showStation(Number(s.dataset.station))}})}
render();
